import sys, json

def brief(x, n=220):
    s = x if isinstance(x, str) else json.dumps(x, ensure_ascii=False)
    s = s.replace("\n", " ")
    return s[:n] + ("…" if len(s) > n else "")

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
    except Exception:
        continue
    t = d.get("type")
    ts = d.get("timestamp", "")
    if t == "queue-operation":
        print(f"[{ts}] QUEUE {d.get('operation')}: {brief(d.get('content',''))}")
        continue
    if t in ("user", "assistant"):
        msg = d.get("message", {})
        role = msg.get("role", t)
        content = msg.get("content")
        if isinstance(content, str):
            print(f"[{ts}] {role.upper()}: {brief(content)}")
        elif isinstance(content, list):
            for block in content:
                bt = block.get("type")
                if bt == "text":
                    print(f"[{ts}] {role.upper()} text: {brief(block.get('text',''))}")
                elif bt == "tool_use":
                    print(f"[{ts}] {role.upper()} tool_use {block.get('name')}: {brief(block.get('input',{}))}")
                elif bt == "tool_result":
                    c = block.get("content")
                    print(f"[{ts}] {role.upper()} tool_result: {brief(c)}")
        continue
    if t == "hook_success" or d.get("attachment", {}).get("type"):
        att = d.get("attachment", {})
        print(f"[{ts}] HOOK {att.get('hookName')}: {brief(att.get('content',''))}")
        continue
    # fallback
    print(f"[{ts}] {t}: {brief(d, 150)}")

